package com.example.nafa;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.*;
public class ProfileActivity extends Activity{
 LinearLayout c;FirebaseFirestore db;String uid;TextView name,info;
 public void onCreate(Bundle b){super.onCreate(b);db=FirebaseFirestore.getInstance();uid=FirebaseAuth.getInstance().getUid();build();load();}
 void build(){c=Ui.col(this);c.setPadding(20,20,20,20);TextView title=Ui.title(this,"حسابي");c.addView(title);name=Ui.text(this,"...",26,getColor(R.color.nafa_text),true);name.setGravity(Gravity.CENTER);c.addView(name,new LinearLayout.LayoutParams(-1,60));info=Ui.text(this,"",14,getColor(R.color.nafa_hint),false);info.setGravity(Gravity.CENTER);c.addView(info,new LinearLayout.LayoutParams(-1,45));Button tools=Ui.button(this,"إدارة أدواتي",true),reviews=Ui.button(this,"التقييمات",false),settings=Ui.button(this,"الإعدادات",false),notes=Ui.button(this,"الإشعارات",false),logout=Ui.button(this,"تسجيل الخروج",false);for(Button b:new Button[]{tools,reviews,settings,notes,logout}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,54);p.setMargins(0,7,0,0);c.addView(b,p);}tools.setOnClickListener(v->startActivity(new android.content.Intent(this,MyToolsActivity.class)));reviews.setOnClickListener(v->startActivity(new android.content.Intent(this,ReviewsActivity.class)));settings.setOnClickListener(v->startActivity(new android.content.Intent(this,SettingsActivity.class)));notes.setOnClickListener(v->startActivity(new android.content.Intent(this,NotificationsActivity.class)));logout.setOnClickListener(v->confirmLogout());ScrollView s=Ui.scroll(this);s.addView(c);setContentView(s);}
 void load(){db.collection("users").document(uid).get().addOnSuccessListener(d->{name.setText(d.getString("fullName"));info.setText(d.getString("email")+"\\n"+d.getString("phone"));});}
 void confirmLogout(){new AlertDialog.Builder(this).setTitle("تسجيل الخروج").setMessage("هل أنت متأكد من تسجيل الخروج؟").setNegativeButton("إلغاء",null).setPositiveButton("تسجيل الخروج",(d,w)->{FirebaseAuth.getInstance().signOut();startActivity(new android.content.Intent(this,LoginActivity.class));finishAffinity();}).show();}
}